{"packet_id":"D041-01","doc_id":"D041","jurisdiction":"Los Angeles, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"Los Angeles Rent Stabilization Ordinance rent increase limits","requirement":"Landlords may raise rent only once every 12 months, by the allowable rent increase percentage; capital improvement, renovation, seismic and other pass-through increases need LAHD approval. Since February 2, 2026 no extra utility or dependent percentage may be added.","key_value":"Once every 12 months, at the allowable rent increase percentage","coverage_conditions":"Rental properties first built on or before October 1, 1978, plus replacement units under LAMC Section 151.28, in the City of Los Angeles: apartments, condos, townhomes, duplexes, rooms rented 30+ days, ADUs, mobile homes.","applicability":{"conditions":[{"type":"built","role":"covered","op":"on_or_before","date":"1978-10-01","basis":"construction"},{"type":"other","text":"Luxury exemption where the landlord applies and establishes rent charged on or before May 31, 1978"}],"per_tenancy":"Condominium and townhome rent amounts are not regulated for tenancies that commenced after December 31, 1995.","coverage_quotes":["Generally, the RSO applies to rental properties that were first built on or before October 1, 1978, as well as replacement units under LAMC Section 151.28","Condominium (Rent amount is not regulated for tenancies that commenced after December 31, 1995)","Luxury Exemption: A landlord can apply for an exemption from the RSO if they can establish the monthly rent charged on or before May 31, 1978"]},"exemptions":"Luxury exemption for units whose rent on or before May 31, 1978 was high; temporary exemptions for previously exempted units; condominium and townhome rent for tenancies commencing after December 31, 1995.","penalty":null,"effective_date":null,"valid_through":null,"citation":"Los Angeles Rent Stabilization Ordinance (L.A.M.C. §151.00 et seq.)","quoted_span":"Rent may be increased once every 12 months by the allowable rent increase percentage","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D041-01","doc_id":"D041","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Los Angeles Rent Stabilization Ordinance just cause eviction rules","requirement":"Landlords may evict RSO tenants only for listed at-fault reasons (nonpayment, lease violation, nuisance, illegal use) or no-fault reasons (owner move-in, demolition, government order); notices must be filed with LAHD within 3 business days and no-fault evictions require relocation assistance.","key_value":"3 business days to file notice; relocation payment for no-fault evictions","coverage_conditions":"All rental units subject to the City of Los Angeles Rent Stabilization Ordinance: properties first built on or before October 1, 1978, plus replacement units.","applicability":{"conditions":[{"type":"built","role":"covered","op":"on_or_before","date":"1978-10-01","basis":"construction"}],"per_tenancy":null,"coverage_quotes":["Generally, the RSO applies to rental properties that were first built on or before October 1, 1978, as well as replacement units under LAMC Section 151.28"]},"exemptions":null,"penalty":null,"effective_date":null,"valid_through":null,"citation":"L.A.M.C. § 151.09","quoted_span":"All notices to terminate a tenancy for all rental units subject to City’s Rent Stabilization Ordinance (RSO) must be filed with the Los Angeles Housing Department (LAHD) within three (3) business days of service on the tenant","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D041-01","n_rules":2,"note":null}

